      {
        "name": "Cornell LII: 9 CFR § 319.140 Sausage",
        "url": "https://www.law.cornell.edu/cfr/text/9/319.140"
      },
      {
        "name": "Cornell LII: 9 CFR § 319.141 Fresh pork sausage",
        "url": "https://www.law.cornell.edu/cfr/text/9/319.141"
      },
